export const FLAG_MEANINGS: { [key in ISOCountryCode]?: FlagMeaning } = {"AF":{"description":"three equal vertical bands of black (left), red, and green, with the national emblem in white centered on the red band and slightly overlapping the other bands; the emblem shows a mosque with a pulpit and flags on either side; below the mosque are Eastern Arabic numerals for the solar year 1298 (1919 in the Gregorian calendar, the year of Afghan independence from the UK); a border of wheat sheaves circles the mosque; above the mosque is an Arabic inscription of the Shahada (Muslim creed), with rays of the rising sun over the Takbir (Arabic expression meaning \"God is great\"); under the mosque is a scroll with the name Afghanistan","meaning":"black stands for the past, and red for the blood shed for independence; green can represent hope for the future, agricultural prosperity, or Islam","history":"Afghanistan had more changes to its national flag in the 20th century -- 19 by one count -- than any other country; the colors black, red, and green appeared on most of them"},"AL":{"description":"red with a black two-headed eagle in the center","meaning":"Albanians traditionally see themselves as descendants of the eagle; they refer to themselves as \"Shqiptare,\" which translates as \"sons of the eagle\"","history":"the design is said to originate with 15th-century Albanian hero Georgi Kastrioti SKANDERBEG, who led a successful uprising against the Ottoman Turks"},"AD":{"description":"three vertical bands of blue (left side), yellow, and red, with the national coat of arms centered in the yellow band, which is slightly wider than the other two; the coat of arms features a quartered shield with the emblems of Urgell, Foix, Bearn, and Catalonia; the motto reads VIRTUS UNITA FORTIOR (Strength United is Stronger)","meaning":"the flag combines the blue and red French colors with the red and yellow of Spain to symbolize Franco-Spanish protection"},"AO":{"description":"two equal horizontal bands of red (top) and black with a centered yellow emblem of a five-pointed star inside half a cogwheel, crossed by a machete (in the style of a hammer and sickle)","meaning":"red stands for liberty and black for the African continent; the emblem symbolizes workers and peasants"},"AG":{"description":"red, with an inverted isosceles triangle in the center that spans the flag from top to bottom; the triangle contains three horizontal bands of black (top), light blue, and white, with a yellow rising sun in the black band","meaning":"the sun stands for the dawn of a new era, black for the African heritage of most of the population, blue for hope, and red for the dynamism of the people; the \"V\" shape of the triangle stands for victory; the yellow, blue, and white colors are also meant to evoke the country's tourist attractions of sun, sea, and sand"},"AR":{"description":"three equal horizontal bands of sky blue (top), white, and sky blue; centered in the white band is a radiant yellow sun with a human face that is known as the Sun of May","meaning":"the colors represent the clear skies and snow of the Andes Mountains; the sun commemorates the first mass demonstration in favor of independence on 25 May 1810, when the sun broke through the clouds; the sun is designed to look like Inti, the Incan god of the sun"},"AM":{"description":"three equal horizontal bands of red (top), blue, and orange","meaning":"red stands for the blood shed for liberty, blue for the Armenian skies and hope, and orange for the land and the courage of the workers who farm it"},"AU":{"description":"blue, with the UK flag in the upper-left quadrant and a large seven-pointed star in the lower-left quadrant; on the right half is a representation of the Southern Cross constellation in white, with one small five-pointed star and four larger seven-pointed stars","meaning":"the largest star is known as the Commonwealth or Federation Star and represents the federation of the Australian colonies in 1901; the star has one point for each of the six original states, plus one representing all of Australia's internal and external territories"},"AT":{"description":"three equal horizontal bands of red (top), white, and red","history":"one of the oldest national flags in the world; according to tradition, after a fierce battle in the Third Crusade in 1191, Duke Leopold V of Austria's white tunic became blood-spattered; when his sash was removed, a white band was revealed, and the red-white-red color combination was adopted as his banner"},"AZ":{"description":"three equal horizontal bands of sky blue (top), red, and green; a vertical crescent moon and an eight-pointed star in white are centered in the red band","meaning":"the blue band stands for Azerbaijan's Turkic heritage, red for modernization and progress, and green for Islam; the crescent moon and star are a Turkic insignia; the eight star points represent the eight Turkic peoples of the world"},"BS":{"description":"three equal horizontal bands of aquamarine (top), gold, and aquamarine, with a black equilateral triangle based on the left side","meaning":"the band colors represent the islands' golden beaches surrounded by the aquamarine sea; black stands for the vigor and force of a united people, and the triangle for the people's enterprise and determination"},"BH":{"description":"red, with a white serrated band of five white points on the left side","meaning":"red is the traditional color for flags of Persian Gulf states; the five points represent the five pillars of Islam","history":"until 2002, the flag had eight white points, but this was reduced to five to avoid confusion with the Qatari flag"},"BD":{"description":"green field with a large red disk shifted slightly to the left","meaning":"the red disk represents the rising sun and the sacrifice to achieve independence; the green field symbolizes the lush vegetation of Bangladesh"},"BB":{"description":"three equal vertical bands of ultramarine blue (left side), gold, and ultramarine blue with a black trident head centered on the gold band","meaning":"blue stands for the sea and sky, and gold for the beaches; the trident head represents independence and a break with the past"},"BY":{"description":"red horizontal band (top), with a green horizontal band below that is half the width of the red band; a white vertical stripe on the left side has traditional Belarusian designs in red","meaning":"the red stands for past struggles to escape oppression, and the green for hope and the country's forests"},"BE":{"description":"three equal vertical bands of black (left side), yellow, and red","history":"the vertical design was based on the flag of France; the colors are from the arms of the duchy of Brabant (yellow lion with red claws and tongue on a black field)"},"BZ":{"description":"royal blue with a narrow red stripe along the top and the bottom edges; the coat of arms is on a large white disk at the center and shows a shield flanked by two workers in front of a mahogany tree, with the motto SUB UMBRA FLOREO (I Flourish in the Shade) on a scroll at the bottom; a green garland of 50 mahogany leaves rings the coat of arms","meaning":"the figures, the mahogany tree, and the garland refer to the logging industry that led the British to settle Belize; blue and red are the colors of the two main political parties"},"BJ":{"description":"two equal horizontal bands of yellow (top) and red (bottom) to the right, with a vertical green band on the left side","meaning":"green stands for hope and revival, yellow for wealth, and red for courage","history":"uses the colors of the Pan-African movement"},"BT":{"description":"divided diagonally from the lower-left corner to the upper-right corner; the upper triangle is yellow, and the lower triangle is dark orange; centered along the dividing line is a large, stylized black-and-white dragon facing to the right; the dragon is called the Druk (Thunder Dragon) and is the national emblem","meaning":"white stands for purity, and the jewels in the dragon's claws symbolize wealth; the background colors represent the spiritual and secular powers in Bhutan, with orange standing for Buddhism and yellow for the ruling dynasty"},"BO":{"description":"three equal horizontal bands of red (top), yellow, and green, with the coat of arms centered on the yellow band","meaning":"red stands for bravery and the blood of national heroes, yellow for the nation's mineral resources, and green for the land's fertility","history":"in 2009, a presidential decree made it mandatory for a wiphala - - a square, multi-colored flag representing the country's ethnic groups -- to be used alongside the national flag"},"BA":{"description":"a wide blue vertical band on the right side, with a large yellow isosceles triangle in the middle of the flag, based at the top; the rest of the flag is blue, with seven five-pointed white stars and two half-stars along the triangle's hypotenuse","meaning":"the triangle approximates the country's shape, and its three points stand for the Bosniaks, Croats, and Serbs; the stars represent Europe; the colors (white, blue, and yellow) are traditional and are also associated with neutrality and peace"},"BW":{"description":"light blue with a horizontal white-edged black stripe across the middle","meaning":"the blue symbolizes rainwater, and the black and white bands represent racial harmony"},"BR":{"description":"green with a large yellow diamond in the center, showing a blue celestial globe with 27 five-pointed white stars; the globe has a white equatorial band with the motto ORDEM E PROGRESSO (Order and Progress)","meaning":"green stands for the country's forests, and yellow for its mineral wealth, with the diamond representing the country's shape; the blue globe and stars depict the sky over Rio de Janeiro on the morning of 15 November 1889, the day the Republic of Brazil was declared; the number of stars has risen with the creation of new states, from 21 to 27 (one for each state and the Federal District)","history":"the flag was inspired by the former Empire of Brazil's flag (1822-1889)"},"BN":{"description":"yellow with a diagonal white band and second below it in black, both starting from the upper left; the national emblem in red is at the center; the state motto, \"Always render service with God's guidance,\" appears in yellow Arabic script on the emblem's crescent; a ribbon below the crescent reads \"Brunei, the Abode of Peace\"","meaning":"yellow symbolizes the sultanate, and the white and black bands stand for the chief ministers; the emblem includes a royal umbrella (the monarchy), two wings with four feathers (justice, tranquility, prosperity, and peace), two upraised hands (the government's pledge to preserve and promote the people's welfare), and the crescent moon of Islam (the state religion)"},"BG":{"description":"three equal horizontal bands of white (top), green, and red","meaning":"white stands for peace, love, and freedom; green for the country's agricultural wealth; red for the independence struggle and military courage","history":"originally adopted in 1879 as a modified version of the Russian tricolor flag, using green instead of blue; the communist coat of arms was added to the flag in various forms between 1948 and 1990, when it was removed after the communist government collapsed"},"BF":{"description":"two equal horizontal bands of red (top) and green, with a five-pointed yellow star in the center","meaning":"red stands for the country's struggle for independence, green for hope and abundance, and yellow for the country's mineral wealth","history":"uses the colors of the Pan-African movement"},"BI":{"description":"divided by a white diagonal cross into red triangles (top and bottom) and green triangles (on each side) with a white disk at the center bearing three six-pointed red stars outlined in green and arranged in a triangular design","meaning":"green stands for hope and optimism, white for purity and peace, and red for the blood shed in the struggle for independence; the three stars represent the major ethnic groups (Hutu, Twa, Tutsi), as well as unity, work, and progress"},"KH":{"description":"three horizontal bands of blue (top), red (double-width), and blue; a three-towered, stylized white temple outlined in black is in the center of the red band, representing Angkor Wat","meaning":"red and blue are traditional Cambodian colors"},"CM":{"description":"three equal vertical bands of green (left side), red, and yellow, with a small five-pointed yellow star centered in the red band","meaning":"red stands for unity; yellow for the sun, happiness, and the northern savannahs; green for hope and the southern forests; the star is called the \"star of unity;\" the vertical tricolor design is similar to the French flag","history":"uses the colors of the Pan-African movement"},"CA":{"description":"two vertical bands of red on each side, with a white square between them; a large 11-pointed red maple leaf is centered in the white square","meaning":"the maple leaf is a national symbol"},"CV":{"description":"five unequal horizontal bands; the top band of blue is half the height of the flag; under it are three narrow bands of white, red, and white, and a bottom stripe of blue; a circle of 10 five-pointed yellow stars is centered on the red stripe and sits toward the left side of the flag","meaning":"blue stands for the sea and sky; the stripes symbolize the country's formation through peace (white) and effort (red); the stars represent the 10 major islands"},"CF":{"description":"four equal horizontal bands of blue (top), white, green, and yellow with a vertical red band in the center; a five-pointed yellow star sits in the top left corner of the flag, on the blue band","meaning":"combines the pan-African and French flag colors; red stands for blood spilled in the struggle for independence, blue for the sky and freedom, white for peace and dignity, green for hope and faith, and yellow for tolerance; the star represents aspiring to a vibrant future"},"TD":{"description":"three equal vertical bands of blue (left side), gold, and red","meaning":"combines the blue and red French (former colonial) colors with the red and yellow Pan-African colors; blue stands for the sky, hope, and the south of the country; gold for the sun and the desert in the north; red for progress, unity, and sacrifice"},"CL":{"description":"two equal horizontal bands of white (top) and red; a blue square sits in the top left corner of the flag, the same height as the white band; the square has a five-pointed white star in the center","meaning":"the star represents a guide to progress and honor; blue stands for the sky, white for the Andes Mountains, and red for the blood spilled to achieve independence"},"CN":{"description":"red with a large five-pointed yellow star and four smaller ones in the upper-left corner; the small stars are arranged in a vertical arc around the large one","meaning":"red represents revolution; the stars symbolize the four social classes -- the working class, the peasantry, the urban petty bourgeoisie, and the national bourgeoisie (capitalists) -- united under the Communist Party of China"},"CO":{"description":"three horizontal bands of yellow (top, double-width), blue, and red","meaning":"various interpretations of the colors exist; one has yellow for the gold in Colombia's land, blue for the sea, and red for the blood spilled in attaining freedom; another describes them as representing sovereignty and justice (yellow), loyalty and vigilance (blue), and valor and generosity (red); another has the colors standing for liberty, equality, and fraternity"},"KM":{"description":"four equal horizontal bands of yellow (top), white, red, and blue, with a green isosceles triangle based on the left; a vertical white crescent moon is centered in the triangle, with four five-pointed white stars placed vertically in a line between the points of the crescent","meaning":"the horizontal bands and the stars represent the four main islands of the archipelago -- Mwali, N'gazidja, Ndzuwani, and Mahore (Mayotte is a department of France, but claimed by Comoros)"},"CG":{"description":"divided diagonally from the lower-left side by a wide yellow band; the upper triangle (left side) is green, and the lower triangle is red","meaning":"green stands for agriculture and forests, and yellow for the people's friendship and nobility; the meaning of the red color is not noted but has been associated with the struggle for independence"},"CD":{"description":"sky-blue field divided diagonally from the lower-left corner to the upper-right corner by a red stripe bordered with two narrow yellow stripes; a five-pointed yellow star is in the upper-left corner","meaning":"blue stands for peace and hope, red for the blood of the country's martyrs, and yellow for the country's wealth and prosperity; the star symbolizes unity and a brilliant future for the country"},"CR":{"description":"five horizontal bands of blue (top), white, red (double-width), white, and blue, with the coat of arms in a white elliptical disk placed toward the left side of the red band","meaning":"the blue is said to stand for the sky, opportunity, and perseverance; the white for peace, happiness, and wisdom; and the red for the blood shed for freedom, as well as Costa Ricans' generosity and vibrancy","history":"Costa Rica retained the earlier blue-white-blue flag of Central America until 1848 when, in response to revolutions in Europe, it was decided to incorporate the French colors by adding a central red stripe"},"CI":{"description":"three equal vertical bands of orange (left side), white, and green","meaning":"orange stands for the savannah and fertility, white for peace and unity, green for the forests of the south and the hope for a bright future; design based on France's flag"},"HR":{"description":"three equal horizontal bands of red (top), white, and blue -- the pan-Slav colors -- with the Croatian coat of arms in the center, which consists of a main shield (a checkerboard of 13 red and 12 silver fields) with five smaller shields that form a crown over the main shield","meaning":"the small shields represent the five historic regions (from left to right): Croatia, Dubrovnik, Dalmatia, Istria, and Slavonia","history":"Russia's 19th-century flag inspired the pan-Slav colors"},"CU":{"description":"five equal horizontal bands of blue (top, center, and bottom) alternating with white; a red equilateral triangle based on the left side has a five-pointed white star in the center","meaning":"the blue bands stand for the islands' three former departments: Central, Occidental, and Oriental; the white bands for the purity of the independence ideal; the triangle for liberty, equality, and fraternity; the red color for the blood shed in the independence struggle; the white star, called \"La Estrella Solitaria\" (the Lone Star), lights the way to freedom and was inspired by the state flag of Texas"},"CY":{"description":"a copper-colored silhouette of the island is centered on a white field above two crossed green olive branches","meaning":"the olive branches symbolize hope for peace and reconciliation between the Greek and Turkish communities"},"CZ":{"description":"two equal horizontal bands of white (top) and red with a blue isosceles triangle based on the left side"},"DK":{"description":"red field with a white cross that extends to the edges of the flag; the vertical part of the cross is shifted to the left","history":"referred to as the Dannebrog (Danish flag) and is one of the oldest national flags in the world; the origin of the design is unclear; one legend says that the banner fell from the sky during an early-13th-century battle and inspired the royal army to victory; in actuality, the flag may derive from a crusade banner"},"DJ":{"description":"two equal horizontal bands of light blue (top) and light green, with a white isosceles triangle based on the left side that has a five-pointed red star in the center","meaning":"blue stands for sea, sky, and the Issa Somali people, green for earth and the Afar people, and white for peace; the red star stands for the struggle for independence and unity"},"DM":{"description":"green with a centered cross of three equal bands in yellow, black, and white; in the center of the cross is a red disk with a Sisserou parrot surrounded by 10 five-pointed green stars edged in yellow","meaning":"the stars represent the 10 administrative divisions (parishes); green symbolizes the island's lush vegetation; the tricolor cross represents the Christian Trinity; yellow stands for sunshine, the primary agricultural products (citrus and bananas), and the Carib people; black for the rich soil and the African heritage of most citizens; white for rivers, waterfalls, and the purity of aspirations; the red disc for social justice"},"DO":{"description":"a centered white cross extends to the edges and divides the flag into four rectangles; the top ones are ultramarine blue (left side) and vermilion red, and the bottom ones are vermilion red (left side) and ultramarine blue; a small coat of arms with a shield supported by a laurel branch and a palm branch is at the center of the cross; above the shield, a blue ribbon displays the motto DIOS, PATRIA, LIBERTAD (God, Fatherland, Liberty); below the shield, REPUBLICA DOMINICANA is on a red ribbon; on the shield, a Bible is opened to a verse that reads \"Y la verdad nos hara libre\" (And the truth shall set you free)","meaning":"blue stands for liberty, white for salvation, and red for the blood of heroes"},"DZ":{"description":"two equal vertical bands of green (left) and white; a red, five-pointed star inside a red crescent, centered over the two-color boundary","meaning":"the colors represent Islam (green), purity and peace (white), and liberty (red); the crescent and star are also Islamic symbols, but the crescent is more closed than those of other Muslim countries because Algerians believe the long crescent horns bring happiness"},"EC":{"description":"three horizontal bands of yellow (top, double-width), blue, and red, with the coat of arms at the center of the flag","meaning":"yellow stands for sunshine, grain, and mineral wealth; blue for the sky, sea, and rivers; red for patriots' blood spilled in the struggle for freedom and justice"},"EG":{"description":"three equal horizontal bands of red (top), white, and black; centered in the white band is the national emblem, a gold Eagle of Saladin; it faces the left side, with a shield on its chest, above a scroll with the country's name in Arabic","meaning":"the band colors derive from the Arab Liberation flag and represent oppression (black) overcome through bloody struggle (red), to be replaced by a bright future (white)"},"SV":{"description":"three equal horizontal bands of cobalt blue (top), white, and cobalt blue, with the national coat of arms centered in the white band; the coat of arms has a round emblem with the words REPUBLICA DE EL SALVADOR EN LA AMERICA CENTRAL around it","meaning":"the blue bands stand for the Pacific Ocean and the Caribbean Sea, and the white for the land, as well as peace and prosperity","history":"the banner is based on the former blue-white-blue flag of the Federal Republic of Central America"},"GQ":{"description":"three equal horizontal bands of green (top), white, and red, with a blue isosceles triangle based on the left side and the coat of arms centered in the white band; the coat of arms has six six-pointed yellow stars (representing the mainland and five offshore islands) above a gray shield with a silk-cotton tree; below is a scroll with the motto UNIDAD, PAZ, JUSTICIA (Unity, Peace, Justice)","meaning":"green stands for the jungle and natural resources, blue for the sea, white for peace, and red for the fight for independence"},"ER":{"description":"a red isosceles triangle (based on the left side) divides the flag into two right triangles; the upper triangle is green, the lower is blue; a gold wreath around a gold olive branch is on the left side of the red triangle","meaning":"green stands for the country's agriculture economy, red for the blood shed in the fight for freedom, and blue for the sea's bounty; the shape of the red triangle mimics the country's shape"},"EE":{"description":"three equal horizontal bands of blue (top), black, and white","meaning":"blue stands for faith, loyalty, and devotion, and also the sky, sea, and lakes; black for the country's soil and the Estonian people's past suffering; white for striving for enlightenment and virtue and also for birch bark, snow, and summer nights illuminated by the midnight sun"},"ET":{"description":"three equal horizontal bands of green (top), yellow, and red, with a light blue disk centered on the three bands; on the disk is a yellow pentagram with single yellow rays emanating from the angles between the points","meaning":"green stands for hope and the land's fertility, yellow for justice and harmony, and red for sacrifice and heroism; the blue of the disk symbolizes peace, and the pentagram represents the Ethiopian people's unity and equality","history":"the emblem in the center of the current flag was added in 1996"},"FJ":{"description":"light blue with the UK flag in the upper-left quadrant and the Fijian shield centered on the right half of the flag; the shield shows a yellow lion holding a coconut above a white field quartered by the cross of Saint George; the four quarters depict sugarcane, a palm tree, a banana bunch, and a white dove","meaning":"blue symbolizes the Pacific Ocean"},"FI":{"description":"white with a blue cross extending to the edges of the flag; the cross is shifted to the left in the style of the Dannebrog (Danish flag)","meaning":"the blue stands for the country's thousands of lakes, and the white for snow"},"FR":{"description":"three equal vertical bands of blue (left side), white, and red","history":"known as the le tricolore (tricolor), the flag dates to 1790 and the French Revolution, when the traditional color of white was combined with the blue and red of the Paris militia; for the first four years of the flag's use (1790-94), the order of colors was reversed (red-white-blue)"},"GA":{"description":"three equal horizontal bands of green (top), yellow, and blue","meaning":"green stands for the country's forests and natural resources, gold for the equator and the sun, and blue for the sea"},"GM":{"description":"three equal horizontal bands of red (top), blue with white edges, and green","meaning":"red stands for the sun and the savannah, blue for the Gambia River, and green for forests and agriculture; the white stripes denote unity and peace"},"GE":{"description":"white rectangle with a central red cross extending to all four sides of the flag; each of the four quadrants displays a small red bolnur-katskhuri cross (also known as Bolnisi cross), which has equal-length arms that are slightly wider at the end than in the center","history":"sometimes referred to as the Five-Cross Flag, the design is based on a 14th-century banner of the Kingdom of Georgia"},"DE":{"description":"three equal horizontal bands of black (top), red, and gold","history":"the colors can be traced back to the medieval banner of the Holy Roman Emperor -- a black eagle with red claws and beak on a gold field"},"GH":{"description":"three equal horizontal bands of red (top), yellow, and green, with a large five-pointed black star centered in the yellow band","meaning":"red stands for the blood shed for independence, yellow for the country's mineral wealth, and green for its forests and natural wealth; the black star is said to be the lodestar of African freedom","history":"uses the colors of the Pan-African movement"},"GR":{"description":"nine equal horizontal stripes of blue alternating with white; a blue square with a white cross is in the upper-left corner","meaning":"the cross symbolizes Greek Orthodoxy, the established religion; there is no set meaning for the stripes and colors"},"GD":{"description":"a rectangle divided diagonally into yellow triangles (top and bottom) and green triangles (left and right), with a wide red border around the flag; three five-pointed yellow stars are centered on the top and bottom of the red border, with one larger yellow star on a red disk at the center of the flag; a small yellow-and-red nutmeg pod is on the left triangle","meaning":"the seven stars stand for the country's administrative divisions, with the central star symbolizing the capital, St. George's; yellow stands for the sun and the warmth of the people, green for vegetation and agriculture, and red for harmony, unity, and courage"},"GT":{"description":"three equal vertical bands of light blue (left side), white, and light blue, with the coat of arms centered in the white band; the coat of arms includes a green-and-red quetzal (the national bird), a scroll with the inscription LIBERTAD 15 DE SEPTIEMBRE DE 1821 (the original date of independence from Spain), a pair of crossed rifles, and a pair of crossed swords; a laurel wreath frames the objects","meaning":"the rifles stand for Guatemala's willingness to defend itself, the swords for honor, and the laurel wreath for victory; blue stands for the Pacific Ocean and Caribbean Sea, and white for peace and purity"},"GN":{"description":"three equal vertical bands of red (left side), yellow, and green","meaning":"red stands for the people's sacrifice for liberation and work; yellow for the sun, the riches of the earth, and justice; green for the country's vegetation and unity","history":"uses the colors of the Pan-African movement"},"GW":{"description":"two equal horizontal bands of yellow (top) and green, with a vertical red band on the left side; a five-pointed black star is centered in the red band","meaning":"yellow stands for the sun, green for hope, red for blood shed during the struggle for independence; the black star stands for African unity","history":"uses the colors of the Pan-African movement; the Ghanaian flag heavily influenced the design"},"GY":{"description":"green with a red isosceles triangle (based on the left side) on top of a long yellow arrowhead shape that extends to the opposite side of the flag; a narrow black border sits between the red and yellow, and a narrow white border between the yellow and green","meaning":"green stands for forest and foliage, yellow for mineral resources and a bright future, white for the rivers, red for zeal and the people's sacrifice, and black for perseverance"},"HT":{"description":"two equal horizontal bands of blue (top) and red; a centered white rectangle bears the coat of arms, which has a palm tree flanked by flags and two cannons above a scroll with the motto L'UNION FAIT LA FORCE (Union Makes Strength)","meaning":"the colors are taken from the French flag and represent the union of ethnic groups"},"VA":{"description":"two vertical bands of yellow (left side) and white, with the arms of the Holy See centered in the white band; the arms show the crossed keys of Saint Peter under the three-tiered papal tiara","meaning":"yellow stands for the pope's spiritual power, and white for his worldly power"},"HN":{"description":"three equal horizontal bands of cerulean blue (top), white, and cerulean blue, with five five-pointed cerulean stars arranged in an \"X\" pattern and centered in the white band","meaning":"the stars represent the members of the former Federal Republic of Central America: Costa Rica, El Salvador, Guatemala, Honduras, and Nicaragua; blue stands for the Pacific Ocean and the Caribbean Sea, and white for the land and the people's peace and prosperity"},"HU":{"description":"three equal horizontal bands of red (top), white, and green","meaning":"folklore attributes virtues to the colors: red for strength, white for faithfulness, and green for hope; alternatively, the red can stand for the blood spilled in defense of the land, white for freedom, and green for pasturelands","history":"the flag dates to the national movement of the 18th and 19th centuries and fuses the medieval colors of the Hungarian coat of arms with the revolutionary tricolor of the French flag"},"IS":{"description":"blue with a red cross outlined in white extending to the edges of the flag; the cross is shifted to the left in the style of the Dannebrog (Danish flag)","meaning":"red stands for the island's volcanic fires, white for the snow and ice fields, and blue for the ocean"},"IN":{"description":"three equal horizontal bands of saffron (top), white, and green, with a blue chakra (24-spoked wheel) centered in the white band","meaning":"saffron stands for courage, sacrifice, and the spirit of renunciation; white for purity and truth; green for faith and fertility; the chakra symbolizes the wheel of life in movement and death in stagnation"},"ID":{"description":"two equal horizontal bands of red (top) and white","meaning":"red stands for courage and white for purity","history":"the colors derive from the banner of the Majapahit Empire of the 13th-15th centuries"},"IR":{"description":"three equal horizontal bands of green (top), white, and red; centered in the white band is the red national emblem, a stylization of the word Allah in the shape of a tulip (a symbol of martyrdom); ALLAH AKBAR (God is Great) in white Arabic script is repeated 11 times along the bottom edge of the green band and 11 times along the top edge of the red band","meaning":"green is the color of Islam and also represents growth, white stands for honesty and peace, and red for bravery and martyrdom"},"IQ":{"description":"three equal horizontal bands of red (top), white, and black; the Takbir (Arabic phrase meaning \"God is great\") in green Arabic script is centered in the white band","meaning":"the colors come from the Arab Liberation flag and stand for oppression (black) overcome through bloody struggle (red), to be replaced by a bright future (white)","history":"the Council of Representatives approved this flag in 2008 as a compromise replacement for the Ba'thist SADDAM-era flag"},"IE":{"description":"three equal vertical bands of green (left side), white, and orange","meaning":"the flag colors have no official meaning, but a common interpretation is that the green stands for the Irish nationalist tradition, orange for the Orange tradition (minority supporters of William of Orange), and white for peace or a lasting truce between the green and the orange"},"IL":{"description":"white with a blue hexagram (six-pointed linear star) known as the Magen David (Star of David or Shield of David) centered between two equal horizontal blue bands near the top and bottom edges of the flag","history":"the design resembles a traditional Jewish prayer shawl ( tallit ), which is white with blue stripes; the hexagram as a Jewish symbol dates back to medieval times"},"IT":{"description":"three equal vertical bands of green (left side), white, and red","meaning":"colors are those of Milan (red and white) combined with the green uniform color of the Milanese civic guard","history":"design inspired by the French flag that Napoleon brought to Italy in 1797"},"JM":{"description":"diagonal yellow cross divides the flag into four triangles, two green (top and bottom) and two black (left and right)","meaning":"green stands for hope, vegetation, and agriculture; black for hardships overcome and to be faced; and yellow for sunshine and natural resources"},"JP":{"description":"white with a large red disk that symbolizes the sun without rays, in the center","history":"the current flag was adopted in 1854, but a sun flag has been in use in Japan since at least 1184; the sun has long been a national symbol: according to tradition, the sun goddess Amaterasu founded the country in the 7th century B.C."},"JO":{"description":"three equal horizontal bands of black (top), white, and green; a red isosceles triangle is on the left side, with a small white seven-pointed star in the center","meaning":"black stands for the Abbassid Caliphate, white for the Ummayyad Caliphate, and green for the Fatimid Caliphate; the triangle stands for the Great Arab Revolt of 1916, and the star's points for the seven verses of the opening Sura (Al-Fatiha) of the Quran, as well as faith in One God, humanity, national spirit, humility, social justice, virtue, and aspirations","history":"the design is based on the Arab Revolt flag of World War I"},"KZ":{"description":"a gold sun with 32 rays above a soaring golden steppe eagle, both centered on a sky-blue background; the left side displays a national pattern called koshkar-muiz (the horns of the ram) in gold","meaning":"the blue color has religious significance for the Turkic peoples and symbolizes cultural and ethnic unity, as well as sky and water; the sun stands for wealth and plenitude, with rays shaped like grain; the eagle has appeared on Kazakh tribal flags for centuries and represents freedom, power, and the flight to the future"},"KE":{"description":"three equal horizontal bands of black (top), red, and green; the red band is edged in white; a large Maasai warrior's shield covering crossed spears is at the center","meaning":"black stands for the majority population, red for the blood shed in the struggle for freedom, green for natural wealth, and white for peace; the shield and crossed spears symbolize the defense of freedom"},"KI":{"description":"the upper half is red with a yellow frigatebird flying over a yellow rising sun, and the lower half is blue with three wavy horizontal white stripes to represent the Pacific Ocean","meaning":"the white stripes represent the Gilbert, Line, and Phoenix island groups; the 17 rays of the sun represent the 16 Gilbert Islands and Banaba (formerly Ocean Island); the frigatebird symbolizes authority and freedom"},"KR":{"description":"white with a red-and-blue yin-yang symbol in the center; a black trigram ( kwae ) from the ancient I Ching (Book of Changes) is in each corner of the white field","meaning":"the flag is called Taegukki; white is a traditional Korean color and represents peace and purity; blue stands for the negative cosmic forces of the yin, and red for the opposite positive forces of the yang; each trigram represents one of the universal elements, which together express the principle of movement and harmony"},"KP":{"description":"three horizontal bands of blue (top), red (triple-width), and blue; the red band is edged in white; on the left side of the red band is a white disk with a red five-pointed star","meaning":"the red band stands for revolutionary traditions, the white for purity, strength, and dignity; blue for sovereignty, peace, and friendship; the red star represents socialism"},"KW":{"description":"three equal horizontal bands of green (top), white, and red, with a black trapezoid based on the left side","meaning":"green stands for fertile fields, white for purity, red for blood on Kuwaiti swords, and black for defeating the enemy","history":"colors and design are based on the Arab Revolt flag of World War I"},"KG":{"description":"red field with a yellow sun in the center that has 40 rays that run counterclockwise on the front of the flag and clockwise on the reverse; in the center of the sun is a red ring crossed by two sets of three lines in a stylized representation of a tunduk, the circular opening at the top of a traditional Kyrgyz yurt","meaning":"the sun's rays represent the Kyrgyz tribes; red stands for bravery and valor, and the sun for peace and wealth"},"LA":{"description":"three horizontal bands of red (top), blue (double-width), and red, with a large white disk centered in the blue band","meaning":"red stands for the blood shed for liberation, and blue for the Mekong River and prosperity; the white disk represents the full moon over the Mekong River and the unity of the people under the Lao People's Revolutionary Party, as well as the country's bright future"},"LV":{"description":"three horizontal bands of maroon (top), white (half-width), and maroon","history":"the flag is one of the older banners in the world -- a medieval chronicle mentions Latvian tribes using a red standard with a white stripe around 1280"},"LB":{"description":"three horizontal bands consisting of red (top), white (middle, double-width), and red (bottom), with a green cedar tree centered on the white band","meaning":"red stands for blood shed for liberation, and white for peace, the snow of the mountains, and purity; the green cedar tree is the national symbol and represents eternity, steadiness, happiness, and prosperity"},"LS":{"description":"three horizontal stripes of blue (top), white, and green; centered on the white stripe is a black mokorotlo , a traditional Basotho straw hat and national symbol","meaning":"blue stands for rain, white for peace, and green for prosperity","history":"the redesigned flag was introduced in 2006 to celebrate 40 years of independence"},"LR":{"description":"11 equal horizontal stripes of red alternating with white; a five-pointed white star sits on a blue square in the upper-left corner","meaning":"the stripes stand for the signatories of the Liberian Declaration of Independence, the blue square for the African mainland, and the star for the freedom granted to ex-slaves; the blue stands for liberty, justice, and fidelity; the white for purity, cleanliness, and guilelessness; the red for steadfastness, valor, and fervor"},"LY":{"description":"three horizontal bands of red (top), black (double-width), and green, with a white crescent and star centered on the black stripe","meaning":"the colors represent the three major regions of the country: red stands for Fezzan, black for Cyrenaica, and green for Tripolitania; the crescent and star represent Islam","history":"the National Transitional Council reintroduced this flag design from the former Kingdom of Libya (1951-69) in 2011 to replace the all-green banner of the QADHAFI regime"},"LI":{"description":"two equal horizontal bands of blue (top) and red, with a gold crown on the left side of the blue band","history":"the colors may derive from the blue-and-red livery used in the principality's household in the 18th century; the prince's crown was added in 1937 to distinguish it from Haiti's flag"},"LT":{"description":"three equal horizontal bands of yellow (top), green, and red","meaning":"yellow stands for golden fields, the sun, light, and goodness; green for the forests, nature, freedom, and hope; red for courage and the blood spilled in defense of the homeland"},"LU":{"description":"three equal horizontal bands of red (top), white, and light blue","history":"the colors are derived from the Grand Duke's coat of arms"},"MG":{"description":"two equal horizontal bands of red (top) and green, with a vertical white band on the left side","meaning":"red stands for sovereignty, green for hope, and white for purity"},"MW":{"description":"three equal horizontal bands of black (top), red, and green, with a rising red sun centered on the black band","meaning":"black stands for ethnic groups, red for the blood shed in the struggle for freedom, and green for nature; the sun represents the hope of freedom for the continent of Africa"},"MY":{"description":"14 equal horizontal stripes of red alternating with white; a dark blue rectangle in the upper-left corner has a yellow crescent and a 14-pointed yellow star","meaning":"the flag is often called Jalur Gemilang (Stripes of Glory); the 14 stripes stand for the equal status of the 13 member states and the federal government; the points on the star represent the unity among these entities; the crescent is a traditional symbol of Islam; blue symbolizes the unity of the Malay people, and yellow is the royal color"},"MV":{"description":"red with a large green rectangle in the center and a vertical white crescent moon centered on the rectangle","meaning":"red stands for those who have sacrificed their lives to defend the country, green for peace and prosperity, and the white crescent is a symbol of Islam"},"ML":{"description":"three equal vertical bands of green (left side), yellow, and red","history":"uses the colors of the Pan-African movement"},"MT":{"description":"two equal vertical bands of white (left side) and red; in the upper-left corner is the George Cross, edged in red","history":"according to legend, the colors come from the red-and-white checkered banner of Count Roger of Sicily, who removed a bicolored corner and granted it to Malta in 1091, but the colors more likely come from the Knights of Saint John, who ruled Malta from 1530 to 1798; in 1942, Britain's King George VI awarded the George Cross to the islanders for their exceptional bravery and gallantry in World War II, and the George Cross bordered in red was added to the flag after independence in 1964"},"MR":{"description":"green with red stripes along the top and bottom edges; on the green field, a five-pointed yellow star is centered over a yellow, upward-pointing crescent moon","meaning":"the crescent, star, and color green are traditional symbols of Islam; green also represents hope for a bright future; yellow stands for the sands of the Sahara, and red for blood shed in the fight for independence"},"MU":{"description":"four equal horizontal bands of red (top), blue, yellow, and green","meaning":"red stands for self-determination and independence; blue for the Indian Ocean; yellow for the new light of independence, golden sunshine, or the bright future; and green for agriculture or the island's lush vegetation"},"MX":{"description":"three equal vertical bands of green (left side), white, and red; Mexico's coat of arms (an eagle with a snake in its beak, perched on a cactus) is centered in the white band","meaning":"green stands for hope, joy, and love; white for peace and honesty; red for hardiness, bravery, strength, and valor"},"FM":{"description":"light blue with four five-pointed white stars centered and arranged in a diamond pattern","meaning":"blue stands for the Pacific Ocean, and the stars for the four island groups of Chuuk, Kosrae, Pohnpei, and Yap"},"MD":{"description":"three equal vertical bands of Prussian blue (left side), chrome yellow, and vermilion red; the Moldavan coat of arms in the center is a dark gold Roman eagle outlined in black, with a red beak and talons; the eagle carries a yellow cross in its beak, a green olive branch in its right talons, and a yellow scepter in its left talons; on the eagle's breast is a red-and-blue shield divided horizontally, with a stylized aurochs head, star, rose, and crescent in black and outlined yellow; the reverse of the flag displays a mirror image of the coat of arms","history":"replaced the communist flag in 1990; the coat of arms is based on traditional designs"},"MC":{"description":"two equal horizontal bands of red (top) and white","history":"uses the colors of the ruling House of Grimaldi; colors have been in use since 1339, making it one of the world's oldest national flags"},"MN":{"description":"three equal vertical bands of red (left side), blue, and red; centered on the left-side red band is the national emblem in yellow, the soyombo, which is an abstract representation of fire, sun, moon, earth, water, and the yin-yang symbol","meaning":"blue stands for the sky, and red for progress and prosperity"},"ME":{"description":"a red field bordered with a narrow golden-yellow stripe; the Montenegrin coat of arms in the center is a double-headed golden eagle, with a crown above; the eagle holds a golden scepter in its right claw and a blue orb in its left; the eagle's breast shield shows a golden lion on a green field in front of a blue sky","meaning":"the eagle symbolizes the unity of church and state; the lion is a symbol of episcopal authority, a reference to the three-and-a-half centuries when Montenegro was ruled as a theocracy"},"MA":{"description":"red with a green pentacle (five-pointed linear star) known as Sulayman's (Solomon's) seal in the center of the flag","meaning":"red and green are traditional colors in Arab flags, although the use of red is more commonly associated with the Arab states of the Persian Gulf; the pentacle represents the five pillars of Islam and the association between God and the nation","history":"the design dates to 1912"},"MZ":{"description":"three equal horizontal bands of green (top), black, and yellow, with a red isosceles triangle based on the left side; the black band is edged in white; centered in the triangle is a five-pointed yellow star with a crossed black-and-white rifle and hoe, on top of an open white book","meaning":"green stands for the riches of the land, white for peace, black for the African continent, yellow for the country's minerals, and red for the fight for independence; the rifle stands for defense and vigilance, the hoe for agriculture, the open book for the importance of education, and the star for Marxism and internationalism"},"MM":{"description":"three equal horizontal stripes of yellow (top), green, and red; centered on the green band is a five-pointed white star that overlaps onto the yellow and red stripes","history":"the design revives the triband colors that Burma used from 1943 to 1945, during the Japanese occupation"},"NA":{"description":"a wide red stripe edged with narrow white stripes divides the flag diagonally from lower-left corner to upper-right corner; the upper triangle is blue and has a golden-yellow, 12-ray sunburst, and the lower triangle is green","meaning":"red stands for the heroism of the people and their determination to build a future of equal opportunity; white stands for peace, unity, tranquility, and harmony; blue stands for the sky and the Atlantic Ocean, the sun for power and existence, and green for vegetation and agricultural resources"},"NR":{"description":"blue with a narrow horizontal gold stripe across the center and a large white 12-pointed star below the stripe on the left side","meaning":"blue stands for the Pacific Ocean; the star indicates the country's location in relation to the equator (the gold stripe), and the 12 points stand for the original tribes of Nauru; the star's white color represents phosphate, the basis of the island's wealth"},"NP":{"description":"crimson red with a blue border, in the shape of two overlapping right triangles; the smaller upper triangle has a stylized white moon, and the larger lower triangle has a 12-pointed white sun","meaning":"red stands for the rhododendron (the national flower) and victory and bravery, and the blue border for peace and harmony; the two triangles are a combination of two pennants that originally symbolized the Himalaya Mountains, but today they refer to Hinduism and Buddhism, the country's two main religions; the moon stands for the serenity of the people, as well as Himalayan shade and cool weather, and the sun for the heat and higher temperatures in the rest of the country"},"NL":{"description":"three equal horizontal bands of bright red (top), white, and cobalt blue","history":"the colors come from WILLIAM I, Prince of Orange; originally the upper band was orange, but the dye would turn red over time, so red was eventually made the permanent color"},"NZ":{"description":"blue with the UK flag in the upper-left quadrant, with four five-pointed red stars edged in white centered in the right half of the flag","meaning":"the stars represent the Southern Cross constellation"},"NI":{"description":"three equal horizontal bands of blue (top), white, and blue, with the national coat of arms centered in the white band; the coat of arms has a triangle with the words REPUBLICA DE NICARAGUA in an arc over it and AMERICA CENTRAL in an arc underneath","meaning":"blue stands for the Pacific Ocean and the Caribbean Sea, and white for the land between the two bodies of water","history":"the banner is based on the former blue-white-blue flag of the Federal Republic of Central America"},"NE":{"description":"three equal horizontal bands of orange (top), white, and green, with an orange disk centered on the white band","meaning":"orange stands for the northern Sahara regions, white for purity and innocence, and green for hope and the fertile and productive southern and western areas, as well as the Niger River; the orange disc represents the sun and the people's sacrifices"},"NG":{"description":"three equal vertical bands of green (left side), white, and green","meaning":"green stands for the country's forests and natural resources, and white for peace and unity"},"NO":{"description":"red with a blue cross outlined in white that extends to the edges of the flag; the the cross is shifted to the left side in the style of the Dannebrog (Danish flag)","meaning":"the colors represent Norway's past political unions with Denmark (red and white) and Sweden (blue)"},"OM":{"description":"three equal horizontal bands of white (top), red, and green, with a vertical red band on the left side; the national emblem (a khanjar dagger in its sheath on top of crossed swords in scabbards) in white is centered near the top of the vertical band","meaning":"white stands for peace and prosperity, red for battles against foreign invaders, and green for the Jebel al Akhdar (Green Mountains) and fertility"},"PK":{"description":"green with a vertical white band on the left side; a large white crescent and star are centered in the green field","meaning":"the crescent, star, and color green are all traditional Islamic symbols; the white band symbolizes the role of religious minorities"},"PW":{"description":"light blue with a large yellow disk to the left side","meaning":"blue stands for the ocean, and the disk for the moon, which is considered a symbol of peace, love, and tranquility"},"PA":{"description":"divided into four equal rectangles; one of the top quadrants is white (left side) with a five-pointed blue star in the center, and the other is plain red; one of the bottom quadrants is plain blue (left side), and the other is white with a five-pointed red star in the center","meaning":"blue and red stand for the main political parties, and white for peace between them; the blue star stands for the civic virtues of purity and honesty, and the red star for authority and law"},"PG":{"description":"divided diagonally from upper-left corner; the upper triangle is red and has a soaring yellow bird of paradise in the center; the lower triangle is black with five five-pointed white stars of the Southern Cross constellation","meaning":"red, black, and yellow are the country's traditional colors; the bird of paradise is an emblem of regional tribal culture and represents the emergence of Papua New Guinea as a nation; the Southern Cross symbolizes the country's connection with Australia and several other countries in the South Pacific"},"PY":{"description":"three equal horizontal bands of red (top), white, and blue, with an emblem centered on the white band; the emblem on one side of the flag is the national coat of arms, which has a five-pointed yellow star in a green wreath with the words REPUBLICA DEL PARAGUAY around it, all inside two circles; the other side of the flag has a circular treasury seal (a yellow lion below a red Cap of Liberty and the words PAZ Y JUSTICIA)","meaning":"red stands for bravery and patriotism, white for integrity and peace, and blue for liberty and generosity"},"PE":{"description":"three equal vertical bands of red (left side), white, and red, with the coat of arms centered on the white band; the coat of arms has a shield with a vicuna, a cinchona tree, and a yellow cornucopia spilling out coins","meaning":"the vicuna represents fauna, the cinchona tree is the source of quinine, and the cornucopia symbolizes mineral wealth; red stands for blood shed for independence, and white for peace"},"PH":{"description":"two equal horizontal bands of blue (top) and red; a white equilateral triangle is based on the left side; the center of the triangle has a yellow sun with eight rays, each split into smaller rays; the triangle's corners each have a small five-pointed yellow star","meaning":"blue stands for peace and justice, red for courage, and the triangle for equality; the rays represent the first eight provinces that sought independence from Spain, and the stars represent the country's three parts: Luzon, Visayas, and Mindanao","history":"the design dates to 1897"},"PL":{"description":"two equal horizontal bands of white (top) and red","meaning":"colors derive from the Polish emblem, a white eagle on a red field"},"PT":{"description":"two vertical bands of green (left side, two-fifths) and red (three-fifths), with the national coat of arms (armillary sphere and national shield) centered on the dividing line","meaning":"explanations for the color meanings are ambiguous, but a popular interpretation says that green symbolizes hope and red the blood of those defending the nation"},"QA":{"description":"maroon with a broad, serrated white band on the left side","meaning":"maroon stands for the blood shed in Qatari wars, and white for peace; the nine-pointed serrated edge is a reference to Qatar's status as the ninth member of the \"reconciled emirates\" after the Qatari-British treaty of 1916 -- the other eight members are Bahrain and the seven that make up the UAE"},"MK":{"description":"a red field with a yellow sun (the Sun of Liberty) in the center, with eight broadening rays extending to the edges","meaning":"the red and yellow colors have long been associated with Macedonia"},"RO":{"description":"three equal vertical bands of blue (left side), yellow, and red","meaning":"the colors come from the principalities of Walachia (red and yellow) and Moldavia (red and blue), which united in 1862 to form Romania","history":"modeled on the French flag; the national coat of arms that used to be centered on the yellow band has been removed"},"RU":{"description":"three equal horizontal bands of white (top), blue, and red","meaning":"colors may have been based on the Dutch flag, but no official meaning is assigned","history":"created when Russia built its first naval vessels, and was used mostly as a naval flag until the 19th century"},"RW":{"description":"three horizontal bands of sky blue (top, double-width), yellow, and green, with a golden sun with 24 rays on the right end of the blue band","meaning":"blue stands for happiness and peace, yellow for economic development and mineral wealth, and green for hope for prosperity and natural resources; the sun symbolizes unity and enlightenment"},"KN":{"description":"divided diagonally from the lower left side by a broad black band with two five-pointed white stars; the black band is edged in yellow; the upper triangle is green, and the lower is red","meaning":"green stands for the island's fertility, red for the struggles of the people from slavery, yellow for year-round sunshine, and black for the people's African heritage; the white stars stand for the islands of Saint Kitts and Nevis but can also express hope and liberty, or independence and optimism"},"LC":{"description":"cerulean blue with a gold isosceles triangle below a black arrowhead; the upper edges of the arrowhead have a white border","meaning":"blue stands for the sky and sea, gold for sunshine and prosperity, and white and black for the ethnic composition of the island; the triangles represent Gros Piton and Petit Piton, the cone-shaped volcanic plugs that are a symbol of the island"},"SM":{"description":"two equal horizontal bands of white (top) and light blue, with the national coat of arms in the center; the main colors come from the shield on the coat of arms, which features three white towers on mountain peaks on a blue field; a wreath and a crown are around the shield, above a scroll with the word LIBERTAS (Liberty)","meaning":"the towers represent the Guaita, Cesta, and Montale castles on Mount Titano; white and blue are said to stand for peace and liberty"},"ST":{"description":"three horizontal bands of green (top), yellow (double-width), and green with two five-pointed black stars in the center of the yellow band and a red isosceles triangle based on the left side","meaning":"green stands for the country's rich vegetation, red for the struggle for independence, and yellow for cocoa, one of the country's main agricultural products; the two stars symbolize the main islands","history":"uses the colors of the Pan-African movement"},"SA":{"description":"green (traditional Islamic color) with the Shahada, or Muslim creed, in large white Arabic script that translates as, \"There is no god but God; Muhammad is the messenger of God;\" the text is above a white horizontal saber pointing to the left","history":"design dates to the early 20th century and is closely associated with the Al Saud family that established the kingdom in 1932; the flag has different sides so that the text reads correctly from right to left and the saber points in the same direction on both sides"},"SN":{"description":"three equal vertical bands of green (left side), yellow, and red, with a small five-pointed green star centered on the yellow band; green stands for Islam, progress, and hope, yellow for natural wealth and progress, and red for sacrifice and determination; the star represents unity and hope","history":"uses the colors of the Pan-African movement"},"RS":{"description":"three equal horizontal stripes of red (top), blue, and white; the national coat of arms is shifted to the left side; the principal field of the coat of arms displays a two-headed white eagle on a red shield; a smaller red shield on the eagle is divided into four quarters by a white cross; a royal crown is on top of the coat of arms","meaning":"red, blue, and white are the pan-Slav colors that represent freedom and revolutionary ideals; the eagle on a red shield represents the government; the smaller shield represents the country; the meaning and origin of the curved white symbols in each quarter are not clear"},"SC":{"description":"five expanding bands of blue, yellow, red, white, and green, radiating from the bottom left corner","meaning":"the bands symbolize a dynamic new country moving into the future; blue stands for the sky and sea, yellow for the sun giving light and life, red for the people's determination to work for the future in unity and love, white for social justice and harmony, and green for the land and natural environment"},"SL":{"description":"three equal horizontal bands of light green (top), white, and light blue","meaning":"green stands for agriculture, mountains, and natural resources; white for unity and justice; and blue for the sea and the natural harbor in Freetown"},"SG":{"description":"two equal horizontal bands of red (top) and white; a vertical white crescent is on the left side of the red band, with a circle of five five-pointed white stars to the right of the crescent","meaning":"red stands for brotherhood and equality, and white for purity and virtue; the waxing crescent moon symbolizes a young nation on the ascendancy; the stars represent the national ideals of democracy, peace, progress, justice, and equality"},"SK":{"description":"three equal horizontal bands of white (top), blue, and red; the national coat of arms (a red shield bordered in white, with a white double-barred cross of St. Cyril and St. Methodius on top of three blue hills) is centered over the bands but offset to the left","meaning":"white, blue, and red are the pan-Slav colors"},"SI":{"description":"three equal horizontal bands of white (top), blue, and red; the Slovenian seal (a shield with Triglav, the country's highest peak, in white on a blue background) is at the center, with two wavy blue lines under it; three six-pointed stars in an inverted triangle appear on the upper-left","meaning":"the wavy lines represent seas and rivers; the colors come from the medieval coat of arms of the Duchy of Carniola; the stars come from the coat of arms of the Counts of Celje (a Slovene dynastic house)"},"SB":{"description":"divided diagonally by a yellow stripe from the lower-left corner; the upper triangle (left side) is blue with five five-pointed white stars in an \"X\" pattern; the lower triangle is green","meaning":"blue stands for the ocean, green for the land, and yellow for sunshine; the five stars stand for the main island groups"},"SO":{"description":"light blue with a large white five-pointed star in the center","meaning":"the blue field was originally influenced by the UN flag but today is said to represent the sky and the Indian Ocean; the five points of the star represent the regions in the horn of Africa where Somali people live: the former British Somaliland and Italian Somaliland (which together make up Somalia), Djibouti, Ogaden (Ethiopia), and the Northeast Province (Kenya)"},"ZA":{"description":"two equal-width horizontal bands of red (top) and blue separated by a central green band that splits into a horizontal Y; a black isosceles triangle is in the Y, with narrow yellow bands around it; the red and blue bands are bordered by narrow white stripes","meaning":"the colors have no official meaning, but the Y stands for \"the convergence of diverse elements within South African society, taking the road ahead in unity\""},"ES":{"description":"three horizontal bands of red (top), yellow (double-width), and red, with the national coat of arms on the left side of the yellow band; the coat of arms shows the emblems of the area's former kingdoms (clockwise from upper left: Castile, Leon, Navarre, and Aragon), which also used red and yellow as their colors; the stylized pomegranate at the bottom of the shield represents Granada; the two columns represent the Pillars of Hercules, which are promontories (Gibraltar and Ceuta) on the Strait of Gibraltar; a red scroll bears the imperial motto of \"Plus Ultra\" (further beyond), referring to Spanish lands outside Europe"},"LK":{"description":"yellow with two panels; the smaller panel on the left has two equal vertical bands of green (left side) and orange; the larger panel has a yellow lion holding a sword on a maroon field, with a yellow bo leaf in each corner","meaning":"the sword stands for national sovereignty; the lion for Sinhalese ethnicity, the strength of the nation, and bravery; the four bo leaves for Buddhism and the four virtues of kindness, friendliness, happiness, and equanimity; orange stands for Tamils, green for Moors, and maroon for the Sinhalese majority; yellow represents other ethnic groups"},"SD":{"description":"three equal horizontal bands of red (top), white, and black, with a green isosceles triangle based on the left side","meaning":"red stands for the struggle for freedom; white for peace, light, and love, black for the people; green for Islam, agriculture, and prosperity","history":"colors and design are based on the Arab Revolt flag of World War I"},"SS":{"description":"three equal horizontal bands of black (top), red, and green; the red band is edged in white; a five-pointed gold star is in the middle of a blue isosceles triangle based on the left side","meaning":"black stands for the people, red for the blood shed in the struggle for freedom, green for the land, and blue for the Nile; the gold star represents the unity of the country's states"},"SR":{"description":"five horizontal bands of green (top, double-width), white, red (quadruple-width), white, and green (double-width); a five-pointed yellow star is centered on the red band","meaning":"red stands for progress and love, green for hope and fertility, and white for peace, justice, and freedom; the star represents the unity of ethnic groups"},"SZ":{"description":"three horizontal bands of blue (top), red (triple-width), and blue; the red band is edged in yellow, with a large black-and-white shield in the center that covers two horizontal spears and a staff with feather tassels","meaning":"blue stands for peace and stability, red for past struggles, and yellow for the mineral resources of the country; the shield, spears, and staff symbolize protection from enemies, and the shield colors stand for ethnic groups living in peaceful coexistence"},"SE":{"description":"blue with a golden yellow cross extending to the edges of the flag; the cross is shifted to the left side in the style of the Dannebrog (Danish flag)","meaning":"the colors come from the Swedish coat of arms"},"CH":{"description":"red square with an equal-armed white cross in the center that does not extend to the edges of the flag","history":"the origin of the flag is unclear, but a white cross was used to identify Swiss Confederation troops at the Battle of Laupen (1339)"},"SY":{"description":"three equal horizontal bands of green (top), white, and black; three five-pointed red stars in a horizontal line, centered on the white band","meaning":"the design is the same as a previous Syrian national flag (in use 1932-58 and 1961-63), but it is still unclear if the elements will retain the same meanings; the bands formerly represented Syria’s past rulers: white (Umayyad Caliphate), black (Abbasid Caliphate), and green (Rashidun Caliphate); the first star represented Damascus, Aleppo, and Deir ez-Zor, the three administrative subdivisions in Syria in the 1930s; the second star stood for Jabal Druze (the Mountain of the Druze), and the third star for the Alawite Mountains","history":"in 2011, opponents to the Asad regime adopted the flag; in 2025, it became the new national flag, replacing the two-star design"},"TW":{"description":"red field with a dark blue rectangle in the upper-left corner, bearing a white sun with 12 triangular rays","meaning":"blue stands for liberty, justice, and democracy; red for fraternity, sacrifice, and nationalism; white for equality, frankness, and the people's livelihood; the 12 rays represent the months of the year and the traditional Chinese hours (each ray equals two hours)","history":"the blue-and-white design of the canton (symbolizing the sun of progress) dates to 1895"},"TJ":{"description":"three horizontal stripes of red (top), a wider stripe of white, and green; a gold crown under seven five-pointed gold stars is in the center of the white stripe","meaning":"red stands for the sun, victory, and the unity of the nation; white for purity, cotton, and mountain snows; green for Islam and nature's bounty; the crown symbolizes the Tajik people; the stars represent the number seven, which is considered a symbol of perfection and the embodiment of happiness"},"TZ":{"description":"divided diagonally by a yellow-edged black band, from the lower left corner to the upper right corner; the upper triangle (left side) is green, and the lower is blue","meaning":"colors come from the flags of Tanganyika and Zanzibar; green stands for natural vegetation, gold for rich mineral deposits, black for the Swahili people, and blue for lakes and rivers, as well as the Indian Ocean"},"TH":{"description":"five horizontal bands of red (top), white, blue (double-width), white, and red","meaning":"red stands for the nation and the blood of life, white for religion and the purity of Buddhism, and blue for the monarchy"},"TL":{"description":"red with a black isosceles triangle (based on the left side) on a slightly longer yellow arrowhead that extends to the center of the flag; a white star is in the center of the black triangle","meaning":"yellow stands for past colonialism, black for obscurantism that needs to be overcome, and red for the struggle for freedom; the white star represents peace and a guiding light"},"TG":{"description":"five equal horizontal bands of green (top and bottom) alternating with yellow; a five-pointed white star on a red square is in the upper-left corner","meaning":"the five horizontal stripes stand for the country's regions; red stands for the people's loyalty and patriotism; green for hope, fertility, and agriculture; yellow for mineral wealth and faith that hard work and strength will bring prosperity; the star symbolizes life, purity, peace, dignity, and national independence","history":"uses the colors of the Pan-African movement"},"TO":{"description":"red with a red cross on a white rectangle in the upper-left corner","meaning":"the cross stands for Christianity in Tonga, red for Christ's blood and sacrifice, and white for purity"},"TT":{"description":"red with a white-edged black diagonal band from the upper left to the lower right","meaning":"the colors represent the elements of earth, water, and fire; black also stands for the wealth of the land and the dedication of the people; white for the sea, the purity of the country's aspirations, and equality; red for the sun, the vitality of the land, and the people's courage and friendliness"},"TN":{"description":"red with a white disk in the center that displays a red crescent around a five-pointed red star","meaning":"red stands for martyrs' blood shed the fight against oppression, and white for peace; the crescent and star are traditional symbols of Islam","history":"resembles the Ottoman flag (red banner with white crescent and star), a reference to Tunisia's history as part of the Ottoman Empire"},"TR":{"description":"red with a vertical white crescent moon and five-pointed white star centered just outside the crescent's opening","meaning":"the flag colors and designs closely resemble the Ottoman Empire's flag; the crescent moon and star serve as insignia for Turkic peoples; according to one interpretation, the flag represents the reflection of the moon and a star in a pool of blood of Turkish warriors"},"TM":{"description":"green field with a vertical red stripe near the left side; the stripe has five tribal guls (designs used in producing carpets) stacked above two crossed olive branches; five five-pointed white stars and a white crescent moon appear in the upper left corner of the main field","meaning":"the green color and crescent moon stand for Islam, the five stars for the country's regions, and the guls for national identity"},"TV":{"description":"light blue with the UK flag in the upper-left quadrant; the right half of the flag has nine five-pointed yellow stars","meaning":"the stars represent a map of the country, with each symbolizing an atoll in the ocean"},"UG":{"description":"six equal horizontal bands of black (top), yellow, red, black, yellow, and red; a white disk is at the center and shows a grey crowned crane (the national symbol)","meaning":"black stands for the African people, yellow for sunshine and vitality, and red for African brotherhood"},"UA":{"description":"two equal horizontal bands of blue (top) and yellow","meaning":"the colors date back to medieval heraldry, but they are sometimes said to represent grain fields under a blue sky"},"AE":{"description":"three equal horizontal bands of green (top), white, and black, with a wider vertical red band on the left side","meaning":"the flag incorporates all four pan-Arab colors, which in this case represent fertility (green), neutrality (white), oil (black), and unity (red); red is a traditional color that was part of all the emirates' flags before their unification"},"GB":{"description":"blue field with the red cross of Saint George (patron saint of England) edged in white on top of the diagonal red cross of Saint Patrick (patron saint of Ireland), which is on top of the diagonal white cross of Saint Andrew (patron saint of Scotland)","history":"the official name is the Union Flag, but commonly called the Union Jack; the design and colors have been the basis for a number of other flags"},"US":{"description":"13 equal horizontal stripes of red (top and bottom) alternating with white; a blue rectangle in the upper-left corner has 50 five-pointed white stars, arranged in nine offset horizontal rows of six stars (top and bottom) alternating with rows of five stars","meaning":"the stars represent the 50 states, and the stripes represent the 13 original colonies; blue stands for loyalty, devotion, truth, justice, and friendship; red for courage, zeal, and fervency; white for purity and rectitude of conduct"},"UY":{"description":"nine equal horizontal stripes of white (top and bottom) alternating with blue; a white square in the upper-left corner has a yellow sun with a human face (outlined in black) known as the Sun of May, with 16 rays that alternate between triangular and wavy","meaning":"the stripes represent the country's nine original departments; the sun refers to the legend of the sun breaking through the clouds on 25 May 1810 as independence was declared from Spain; the sun is said to be Inti, the Inca god of the sun"},"UZ":{"description":"three equal horizontal bands of blue (top), white, and green separated by narrow red stripes with a vertical white crescent moon and 12 five-pointed white stars in the left corner of the top band","meaning":"blue stands for the Turkic peoples and the sky, white for peace and the striving for purity in thoughts and deeds, and green for nature and Islam; the red stripes represent the vital force of all living organisms; the crescent stands for Islam, and the 12 stars for the months and constellations of the Uzbek calendar"},"VU":{"description":"two equal horizontal bands of red (top) and green with a black isosceles triangle (based on the left side); a black-edged yellow stripe in the shape of a horizontal \"Y\" faces the left side and encloses the triangle; a boar's tusk in the triangle circles two crossed namele fern fronds, all in yellow","meaning":"red stands for unity and the blood of men and boars, green for the richness of the islands, and black for the ni-Vanuatu people; the yellow \"Y\" reflects the islands' layout in the Pacific Ocean and symbolizes the light of the Gospel; the boar's tusk is a symbol of prosperity; the ferns represent peace"},"VE":{"description":"three equal horizontal bands of yellow (top), blue, and red, with the coat of arms on the left side of the yellow band and an arc of eight five-pointed white stars centered on the blue band","meaning":"yellow stands for the riches of the land, blue for the courage of its people, and red for the blood shed in attaining independence","history":"the flag retains the three equal horizontal bands and three main colors from the flag of Gran Colombia, the South American republic that broke up in 1830; in 2006, President Hugo CHAVEZ added the eighth star -- the original seven stars represented the country's provinces that united in the war of independence -- to match Simon Bolivar's flag from 1827 and to represent the historic province of Guayana"},"VN":{"description":"red field with a five-pointed yellow star in the center","meaning":"red stands for revolution and blood, and the five-pointed star for the five elements of the populace -- peasants, workers, intellectuals, traders, and soldiers -- that unite to build socialism"},"YE":{"description":"three equal horizontal bands of red (top), white, and black","meaning":"the band colors come from the Arab Liberation flag and represent oppression (black) overcome through bloody struggle (red), to be replaced by a bright future (white)"},"ZM":{"description":"green field with a soaring orange eagle in the upper-right corner; a panel of three vertical bands is under the eagle, in red (left side), black, and orange","meaning":"green stands for the country's natural resources and vegetation, red for the struggle for freedom, black for the people, and orange for the country's mineral wealth; the eagle represents the people's ability to rise above the nation's problems"},"ZW":{"description":"seven equal horizontal bands of green (top), yellow, red, black, red, yellow, and green, with a white isosceles triangle edged in black based on the left side; in the middle of the triangle, a yellow bird is on top of a five-pointed red star","meaning":"the bird represents the long history of the country; white stands for peace, green for agriculture, yellow for mineral wealth, red for the blood shed to achieve independence, and black for the people"},"XK":{"description":"a dark blue field with a gold-colored silhouette of Kosovo in the center, with six five-pointed white stars in a slight arc over it","meaning":"each star represents one of the major ethnic groups of Kosovo: Albanians, Serbs, Turks, Gorani, Roma, and Bosniaks"}}
